   240→    }
   241→
   242→    fn fallback_decode(buf: &mut &[u8]) -> Eip2718Result<Self> {
   243→        Ok(Self::rlp_decode_inner_without_bloom(buf, T::try_from(0)?)?)
   244→    }
   245→}
