   395→    where
   396→        D: Deserializer<'de>,
   397→        T: TryFrom<u8, Error = Eip2718Error>,
   398→    {
   399→        U8::deserialize(deserializer)?.to::<u8>().try_into().map_err(serde::de::Error::custom)
   400→    }
