   490→mod compact {
   491→    use super::*;
   492→    use reth_codecs::{
   493→        Compact,
   494→        __private::{modular_bitfield::prelude::*, Buf},
   495→    };
   496→
   497→    impl Receipt {
   498→        #[doc = "Used bytes by [`ReceiptFlags`]"]
   499→        pub const fn bitflag_encoded_bytes() -> usize {
   500→            1u8 as usize
   501→        }
   502→        #[doc = "Unused bits for new fields by [`ReceiptFlags`]"]
